export default {
  name: 'c_select_item',
  props: {
    configObj: {
      type: Object
    },
    configNme: {
      type: String
    }
  },
  data () {
    return {
      defaults: {},
      configData: {},
      batchWord: '',
      visible:false,
    }
  },
  created () {
    this.defaults = this.configObj
    this.configData = this.configObj[this.configNme]
  },
  watch: {
    configObj: {
      handler (nVal, oVal) {
        this.configData = nVal[this.configNme]
      },
      immediate: true,
      deep: true
    }
  },
  methods: {
    cancel(num){
      this.visible = false;
      if(num==2){
        let arr = this.batchWord.split('\n');
        let arrNew = [];
        arr.forEach(item=>{
          let obj = {};
          obj['val'] = item;
          arrNew.push(obj)
        })
        this.configData.list = this.configData.list.concat(arrNew);
      }
      this.batchWord = '';
    },
    addHotTxt () {
      let obj = {
        val: ''
      };
      this.configData.list.push(obj)
    },
    // 删除数组
    bindDelete (index) {
      this.configData.list.splice(index, 1)
    },
  }
}
